// build/icons.mjs — the drawn icons. Reads the Lucide icon set (ISC, https://lucide.dev) from a folder of its SVGs and writes:
//   canvas/runtime/icons.gen.js       the canvas's own interface glyphs (the UI list below — no domain words)
//   tools/<d>/core/icons.gen.js        every name tools/<d>/icons.json uses, and its tool / suite / category / mode map
// Usage: node build/icons.mjs <path to lucide-static/icons>   (npm pack lucide-static; the generated files are committed,
// so the app never needs the package). Run it again after changing an icons.json.
import fs from 'fs'; import path from 'path';
const SRC = process.argv[2]; if (!SRC || !fs.existsSync(SRC)) { console.error('usage: node build/icons.mjs <lucide-static/icons>'); process.exit(1); }
const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const UI = ['book-open', 'blocks', 'puzzle', 'clapperboard', 'sliders-horizontal', 'cable', 'plus', 'arrow-left', 'x', 'play', 'check', 'arrow-up-right',
  'layers', 'link-2', 'package', 'sliders-vertical', 'arrow-left-right', 'search', 'sparkles', 'wand-sparkles', 'circle-check', 'circle-dashed', 'box', 'hammer', 'square-stack',
  'maximize-2', 'minimize-2', 'chevron-down', 'chevron-right', 'fold-vertical', 'unfold-vertical', 'circle-minus',
  'layout-grid', 'ellipsis', 'square', 'maximize', 'undo-2', 'redo-2', 'panel-bottom', 'graduation-cap', 'library', 'triangle-alert'];
// the full license (ISC, and MIT for the icons derived from Feather, with their list) is copied to LICENSES/lucide.txt; each
// generated file carries the notices and points there (the list of icon names stays out of the domain-free canvas)
const FULL = fs.readFileSync(path.join(SRC, '..', 'LICENSE'), 'utf8');
fs.mkdirSync(path.join(ROOT, 'LICENSES'), { recursive: true }); fs.writeFileSync(path.join(ROOT, 'LICENSES', 'lucide.txt'), FULL);
const LICENSE = FULL.split(/\n---\n/)[0].trim() + '\n\nSome of these icons are derived from Feather — The MIT License (MIT), Copyright (c) 2013-present Cole Bemis.\nThe full text of both licenses, and which icons came from Feather: LICENSES/lucide.txt';
function inner(name) {
  const f = path.join(SRC, name + '.svg'); if (!fs.existsSync(f)) throw new Error('no icon named ' + name);
  const s = fs.readFileSync(f, 'utf8'), m = s.match(/<svg[^>]*>([\s\S]*?)<\/svg>/); if (!m) throw new Error('not an svg: ' + name);
  return m[1].replace(/\s+/g, ' ').replace(/> </g, '><').replace(/ \/>/g, '/>').trim();
}
const head = (what) => `/* GENERATED by build/icons.mjs — do not edit. ${what}\n * Drawn icons from Lucide (https://lucide.dev), used under its license:\n${LICENSE.split('\n').map(l => ' * ' + l).join('\n').replace(/\*\//g, '* /')}\n */\n`;
const set = (names) => Object.fromEntries([...new Set(names)].sort().map(n => [n, inner(n)]));
fs.writeFileSync(path.join(ROOT, 'canvas/runtime/icons.gen.js'), head('The canvas interface glyphs.') + `(window.Icons && window.Icons.add(${JSON.stringify(set(UI))}));\n`);
let n = UI.length;
for (const d of fs.readdirSync(path.join(ROOT, 'tools'))) {
  const mf = path.join(ROOT, 'tools', d, 'icons.json'); if (!fs.existsSync(mf)) continue;
  const M = JSON.parse(fs.readFileSync(mf, 'utf8')), map = {};
  Object.entries(M.tools || {}).forEach(([k, v]) => map[k] = v);
  Object.entries(M.suites || {}).forEach(([k, v]) => map['suite:' + k] = v);
  Object.entries(M.categories || {}).forEach(([k, v]) => map['cat:' + k] = v);   // by the category's label, as ＋ Add shows it
  Object.entries(M.modes || {}).forEach(([k, v]) => map['mode:' + k] = v);
  const names = Object.values(map);
  fs.mkdirSync(path.join(ROOT, 'tools', d, 'core'), { recursive: true });
  fs.writeFileSync(path.join(ROOT, 'tools', d, 'core', 'icons.gen.js'), head(`The ${d} domain's icons (from tools/${d}/icons.json).`) +
    `(window.Icons && (window.Icons.add(${JSON.stringify(set(names))}), window.Icons.map(${JSON.stringify(map)})));\n`);
  n += new Set(names).size; console.log(`${d}: ${Object.keys(map).length} things, ${new Set(names).size} icons`);
}
console.log('icons written:', n);
